from typing import Optional

import pydantic

from ...schemas.rapi.base import BaseRapiResponseSchema


class Entry(pydantic.BaseModel):
    name: str
    path: str
    type: str
    readonly: Optional[bool] = False


class CloudFolderListResultsSchema(pydantic.BaseModel):
    name: str
    path: str
    type: str
    entries: Optional[list[Entry]]


class CloudFolderListResponseSchema(BaseRapiResponseSchema):
    results: CloudFolderListResultsSchema


class CloudInitFileSaveResponseSchema(BaseRapiResponseSchema): ...


class CloudOpenFileResultsSchema(pydantic.BaseModel):
    link: pydantic.AnyHttpUrl


class CloudOpenFileResponseSchema(BaseRapiResponseSchema):
    results: CloudOpenFileResultsSchema


class CloudCancelSaveResponseSchema(BaseRapiResponseSchema): ...
